insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('a6a6a860-f561-5cc8-8486-3532688e9d0a', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Nigeria''s film industry is popularly known as what?', '["Naijawood","Nollywood","Afriwood","Lagoswood"]'::jsonb, 1, 1, 'Nigeria produces more films per year than almost any country on earth.', 'https://en.wikipedia.org/wiki/Nollywood', 'live'),
  ('60c0f91b-8b73-57fb-9f55-39622760ec63', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which 1992 home video is widely credited with launching the Nollywood boom?', '["Glamour Girls","Osuofia in London","Living in Bondage","Rattlesnake"]'::jsonb, 2, 1, 'Living in Bondage starred Kenneth Okonkwo as Andy Okeke.', 'https://en.wikipedia.org/wiki/Living_in_Bondage', 'live'),
  ('84cce232-df80-5b95-be45-f60c9ce8206b', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who played Andy Okeke in the original Living in Bondage?', '["Ramsey Nouah","Pete Edochie","Zack Orji","Kenneth Okonkwo"]'::jsonb, 3, 1, 'Kenneth Okonkwo reprised the role in the 2019 sequel.', 'https://en.wikipedia.org/wiki/Living_in_Bondage', 'live'),
  ('c2559c40-233b-51e8-8121-8ec780cdb59e', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Funke Akindele is famous for playing which comic character?', '["Mama G","Aunty Bisi","Jenifa","Toyin Tomato"]'::jsonb, 2, 1, 'Jenifa first appeared in the 2008 film of the same name.', 'https://en.wikipedia.org/wiki/Funke_Akindele', 'live'),
  ('3d982039-73ef-561c-9c96-18341a245c89', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which reality TV show is hosted by Ebuka Obi-Uchendu?', '["Nigerian Idol","Big Brother Naija","Gulder Ultimate Search","The Voice Nigeria"]'::jsonb, 1, 1, 'Ebuka was himself a housemate in the very first season in 2006.', 'https://en.wikipedia.org/wiki/Big_Brother_Naija', 'live'),
  ('b98b409a-992f-5a10-b937-330a969bb6c0', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Chinedu Ikedieze and Osita Iheme are famously known as which duo?', '["Jenifa and Toyosi","Ajasco and Pa James","Aki and Pawpaw","Osuofia and Mr Ibu"]'::jsonb, 2, 1, 'Their breakout film Aki na Ukwa was released in 2002.', 'https://en.wikipedia.org/wiki/Aki_na_Ukwa', 'live'),
  ('aee81926-3e02-5b15-ad07-b798e03545d1', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which actor starred as the title character in Osuofia in London?', '["Victor Osuagwu","John Okafor","Nkem Owoh","Sam Loco Efe"]'::jsonb, 2, 1, 'Nkem Owoh also sang the hit song ''I Go Chop Your Dollar''.', 'https://en.wikipedia.org/wiki/Osuofia_in_London', 'live'),
  ('a35203c9-b657-57fa-bc8b-545522523527', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'The late John Okafor was best known by which screen name?', '["Chief Zebrudaya","Mr Ibu","Osuofia","Papa Ajasco"]'::jsonb, 1, 1, 'Mr Ibu''s slapstick roles made him one of Nollywood''s best-loved comedians.', 'https://en.wikipedia.org/wiki/John_Okafor', 'live'),
  ('1310f842-df88-5aa3-bf8f-1f1b3562942d', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Kemi Adetiba film follows Lagos crime boss Eniola Salami?', '["The Wedding Party","Gangs of Lagos","Brotherhood","King of Boys"]'::jsonb, 3, 1, 'Sola Sobowale won wide acclaim for playing Eniola Salami.', 'https://en.wikipedia.org/wiki/King_of_Boys', 'live'),
  ('78ca82ad-ab9b-5fb3-a093-e3427a7c794f', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who directed and starred in Lionheart (2018)?', '["Omotola Jalade-Ekeinde","Genevieve Nnaji","Funke Akindele","Mercy Johnson"]'::jsonb, 1, 1, 'Lionheart was the first Netflix original film acquired from Nigeria.', 'https://en.wikipedia.org/wiki/Lionheart_(2018_film)', 'live'),
  ('85d7b2e5-bb9f-5374-ac5d-283e160d7763', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which comedy is about a lavish Lagos wedding between Dunni and Dozie?', '["Chief Daddy","Merry Men","Isoken","The Wedding Party"]'::jsonb, 3, 1, 'The Wedding Party was released in 2016.', 'https://en.wikipedia.org/wiki/The_Wedding_Party_(2016_film)', 'live'),
  ('af5ad9de-bdce-59f0-ae01-6db9d55c54e8', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Patience Ozokwor is popularly called what?', '["Iya Awero","Mama Put","Mama G","Mama Rainbow"]'::jsonb, 2, 1, 'She is famous for playing fierce mother-in-law roles.', 'https://en.wikipedia.org/wiki/Patience_Ozokwor', 'live'),
  ('4b134b69-94aa-5d7a-8ba0-e6144842d9f5', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which skit maker is known for the character ''Mr Macaroni''?', '["Debo Adedayo","Bright Okpocha","Samuel Perry","Maryam Apaokagi"]'::jsonb, 0, 1, 'Mr Macaroni''s catchphrase ''You are doing well!'' went viral online.', 'https://en.wikipedia.org/wiki/Mr_Macaroni', 'live'),
  ('261ae51e-9b0b-54bd-9b7e-b021ab827e77', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Broda Shaggi is the stage character of which comedian?', '["Samuel Animashaun Perry","Atunyota Akpobome","Debo Adedayo","Ayo Makun"]'::jsonb, 0, 1, 'Broda Shaggi is known for his exaggerated Lagos-street persona.', 'https://en.wikipedia.org/wiki/Broda_Shaggi', 'live'),
  ('bc6be626-e4cb-5111-8c0c-99aa44cc20fc', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which comedian is popularly known as ''AY''?', '["Ayodeji Balogun","Ayo Makun","Ayinde Barrister","Ayo Adesanya"]'::jsonb, 1, 1, 'AY starred in and produced 30 Days in Atlanta (2014).', 'https://en.wikipedia.org/wiki/Ayo_Makun', 'live'),
  ('0b5690f2-6573-573b-becd-90e4c43948a3', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'The comedy group famous for recreating Hollywood movie trailers on a budget is?', '["Lagos Boys","Ajegunle Kids","Mushin Crew","Ikorodu Bois"]'::jsonb, 3, 1, 'Their remakes have been shared by Hollywood stars and studios.', 'https://en.wikipedia.org/wiki/Ikorodu_Bois', 'live'),
  ('00be50a6-8e64-5388-b8c8-3a79576deb9b', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which comedian is known by the stage name Basketmouth?', '["Julius Agwu","Bright Okpocha","Francis Agoda","Ayo Makun"]'::jsonb, 1, 1, 'Basketmouth is one of Nigeria''s most successful stand-up comedians.', 'https://en.wikipedia.org/wiki/Basketmouth', 'live'),
  ('ab433ef1-c284-5439-98ae-788f25ab2f5e', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'In which city is most of Nollywood''s English-language production based?', '["Port Harcourt","Kano","Ibadan","Lagos"]'::jsonb, 3, 1, 'Lagos is Nigeria''s commercial hub and largest city.', 'https://en.wikipedia.org/wiki/Nollywood', 'live'),
  ('28828d57-aaac-59ef-a780-3057aba310f5', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which streaming service released Blood Sisters (2022), its first Nigerian original series?', '["Amazon Prime Video","Disney+","Showmax","Netflix"]'::jsonb, 3, 1, 'Blood Sisters was produced by Mo Abudu''s EbonyLife.', 'https://en.wikipedia.org/wiki/Blood_Sisters_(TV_series)', 'live'),
  ('153c538e-d4d9-58f9-9aea-4f49bbdf310a', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who founded the EbonyLife media group?', '["Kemi Adetiba","Jade Osiberu","Bimbo Akintola","Mo Abudu"]'::jsonb, 3, 1, 'EbonyLife TV launched in 2013.', 'https://en.wikipedia.org/wiki/Mo_Abudu', 'live'),
  ('965cfcdf-3b63-54cf-bc17-966577a124b6', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Funke Akindele film became the first Nollywood film to gross over ₦1 billion?', '["Omo Ghetto: The Saga","Battle on Buka Street","A Tribe Called Judah","Jenifa"]'::jsonb, 2, 2, 'A Tribe Called Judah was released in December 2023.', 'https://en.wikipedia.org/wiki/A_Tribe_Called_Judah', 'live'),
  ('6d15b1cb-4bfc-54e0-87f1-c4eaf0ae20fb', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who directed Living in Bondage: Breaking Free (2019)?', '["Ramsey Nouah","Kunle Afolayan","Kemi Adetiba","Tunde Kelani"]'::jsonb, 0, 2, 'It was Ramsey Nouah''s feature directorial debut.', 'https://en.wikipedia.org/wiki/Living_in_Bondage:_Breaking_Free', 'live'),
  ('d7271e73-58e9-559c-8490-685cac23a165', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which veteran actor played Okonkwo in the 1987 TV adaptation of Things Fall Apart?', '["Pete Edochie","Sam Loco Efe","Justus Esiri","Olu Jacobs"]'::jsonb, 0, 2, 'The NTA series made Pete Edochie a household name.', 'https://en.wikipedia.org/wiki/Pete_Edochie', 'live'),
  ('691f87b3-f56c-5d0b-bfa1-18042d6fa0d7', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who wrote the 1958 novel Things Fall Apart?', '["Buchi Emecheta","Cyprian Ekwensi","Wole Soyinka","Chinua Achebe"]'::jsonb, 3, 2, 'It is one of the most widely read African novels ever.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'live'),
  ('7d76c3db-cf54-5f27-8cf0-03e52eb930b1', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which long-running drama series is produced by Wale Adenuga Productions?', '["Checkmate","Tinsel","Super Story","Tales by Moonlight"]'::jsonb, 2, 2, 'Wale Adenuga also created Papa Ajasco.', 'https://en.wikipedia.org/wiki/Super_Story', 'live'),
  ('d1d3da59-10f6-58a8-a109-1a6bc8fe040c', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which classic NTA series began in 1968 and was set in a village school?', '["Mirror in the Sun","Behind the Clouds","Cock Crow at Dawn","The Village Headmaster"]'::jsonb, 3, 2, 'It ran for decades and is one of Africa''s longest-running TV series.', 'https://en.wikipedia.org/wiki/The_Village_Headmaster', 'live'),
  ('620aed74-1893-5b0f-8f1e-39b85f332482', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Chief Zebrudaya was the lead character in which sitcom?', '["Fuji House of Commotion","The New Masquerade","Basi and Company","Papa Ajasco"]'::jsonb, 1, 2, 'Zebrudaya was played by Chika Okpala.', 'https://en.wikipedia.org/wiki/The_New_Masquerade', 'live'),
  ('2b834bf1-09d8-55ec-8bf7-7b30b69f4f7e', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which writer and activist created the 1980s sitcom Basi and Company?', '["Wole Soyinka","Femi Osofisan","Ken Saro-Wiwa","Ola Rotimi"]'::jsonb, 2, 2, 'The show satirised get-rich-quick schemes in Lagos.', 'https://en.wikipedia.org/wiki/Basi_and_Company', 'live'),
  ('2959b568-c3dd-5c8f-b173-774b282208a0', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Africa Magic soap opera premiered in 2008 and is set in the film industry?', '["The Johnsons","Jenifa''s Diary","Hotel Majestic","Tinsel"]'::jsonb, 3, 2, 'Tinsel is one of Nigeria''s longest-running soaps.', 'https://en.wikipedia.org/wiki/Tinsel_(TV_series)', 'live'),
  ('718359e5-20e5-530f-b154-29f78a888819', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which actor became the Delta State Commissioner for Culture and Tourism?', '["Kanayo O. Kanayo","Jim Iyke","Desmond Elliot","Richard Mofe-Damijo"]'::jsonb, 3, 2, 'RMD is one of Nollywood''s most decorated actors.', 'https://en.wikipedia.org/wiki/Richard_Mofe-Damijo', 'live'),
  ('a37b7eca-72e3-553b-99a1-ef9d648b12c4', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who directed the 2016 film The Wedding Party?', '["Niyi Akinmolayan","Kunle Afolayan","Jade Osiberu","Kemi Adetiba"]'::jsonb, 3, 2, 'Kemi Adetiba also directed King of Boys.', 'https://en.wikipedia.org/wiki/Kemi_Adetiba', 'live'),
  ('75404fb7-de00-5f4c-96d2-14a6d8fb8328', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Banky W and Adesua Etomi starred as the couple in which film?', '["Chief Daddy","Sugar Rush","The Wedding Party","Isoken"]'::jsonb, 2, 2, 'The two later married in real life in 2017.', 'https://en.wikipedia.org/wiki/The_Wedding_Party_(2016_film)', 'live'),
  ('83f494ed-3627-59f7-a5cf-2f9d099ae4aa', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'In what year did Big Brother Naija first air (as Big Brother Nigeria)?', '["2001","2006","2017","2010"]'::jsonb, 1, 2, 'The show returned in 2017 after an 11-year break.', 'https://en.wikipedia.org/wiki/Big_Brother_Naija', 'live'),
  ('6a3842b7-a995-5f37-aada-0174239eaa80', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who won Big Brother Naija in 2017, the show''s comeback season?', '["Efe Ejeba","Mercy Eke","Laycon","Miracle Ikechukwu"]'::jsonb, 0, 2, 'Efe''s catchphrase ''Based on logistics'' went viral.', 'https://en.wikipedia.org/wiki/Big_Brother_Naija_(season_2)', 'live'),
  ('68fde35f-7771-53d1-99a1-3d8541c694e0', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Mercy Eke made history in 2019 as Big Brother Naija''s first what?', '["Two-time winner","Diaspora winner","Wildcard winner","Female winner"]'::jsonb, 3, 2, 'Mercy won the fourth season, ''Pepper Dem''.', 'https://en.wikipedia.org/wiki/Big_Brother_Naija_(season_4)', 'live'),
  ('ef92c077-9d0c-501a-be2b-7c136d573d7e', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who won Big Brother Naija season 5 ''Lockdown'' in 2020?', '["Nengi","Vee","Ozo","Laycon"]'::jsonb, 3, 2, 'Laycon is a rapper from Lagos.', 'https://en.wikipedia.org/wiki/Big_Brother_Naija_(season_5)', 'live'),
  ('ecfd08ce-8f5c-5c7f-bae5-534beb90f91e', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Kunle Afolayan film about a Yoruba tailor named Saro was a Netflix hit in 2022?', '["The CEO","Anikulapo","Citation","October 1"]'::jsonb, 1, 2, 'Anikulapo blends folklore with a love story.', 'https://en.wikipedia.org/wiki/Anikulapo', 'live'),
  ('848ff78a-d96c-5aaf-a7a8-2881052b0855', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who directed Gangs of Lagos, Amazon Prime Video''s first Nigerian original film?', '["Kayode Kasum","Jade Osiberu","Kemi Adetiba","Editi Effiong"]'::jsonb, 1, 2, 'Gangs of Lagos premiered in April 2023.', 'https://en.wikipedia.org/wiki/Gangs_of_Lagos', 'live'),
  ('6b24c7c5-a0cc-5f4f-a038-179bf7d1bd54', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Netflix thriller (2023) stars Richard Mofe-Damijo as a grieving father hunting corrupt officials?', '["Gangs of Lagos","Shanty Town","The Black Book","Brotherhood"]'::jsonb, 2, 2, 'The Black Book reached Netflix''s global top 10.', 'https://en.wikipedia.org/wiki/The_Black_Book_(2023_film)', 'live'),
  ('109084c3-d940-580f-a7bb-5d7277c38dbf', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Femi Adebayo starred in which 2023 Netflix epic about warriors?', '["Jagun Jagun","Elesin Oba","Anikulapo","King of Thieves"]'::jsonb, 0, 2, 'Jagun Jagun means ''warrior'' in Yoruba.', 'https://en.wikipedia.org/wiki/Jagun_Jagun', 'live'),
  ('ed575a74-439d-5730-b67a-3c27e9d158d9', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Sola Sobowale played ''Toyin Tomato'' in which popular TV series?', '["The Johnsons","Super Story","Tinsel","Fuji House of Commotion"]'::jsonb, 1, 2, 'The ''Oh Father, Oh Daughter'' storyline made her a star.', 'https://en.wikipedia.org/wiki/Sola_Sobowale', 'live'),
  ('3cd3238c-b8ca-578e-955d-7cd45c9f4095', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Which Amaka Igwe sitcom followed a polygamous Lagos household?', '["My Flatmates","Fuji House of Commotion","The Johnsons","Jenifa''s Diary"]'::jsonb, 1, 2, 'Amaka Igwe also created the drama Checkmate.', 'https://en.wikipedia.org/wiki/Amaka_Igwe', 'live'),
  ('9b60b81f-3e1a-5c65-83fc-e08cf13df6cd', '42db8c25-b9e9-53c7-93b4-093be1ea82f2', 'Who hosted Who Wants to Be a Millionaire? Nigeria?', '["Ebuka Obi-Uchendu","IK Osakioduwa","Frank Edoho","Bovi Ugboma"]'::jsonb, 2, 2, 'Frank Edoho hosted the quiz show for over a decade.', 'https://en.wikipedia.org/wiki/Frank_Edoho', 'live'),
