  ('ec61417c-52dd-5a3a-9ce2-7cb8e9bb532b', '47139ef4-9c94-5d32-a05b-03686b39cf39', '2Baba began his career in which group?', '["Remedies","Trybesmen","Plantashun Boiz","Styl-Plus"]'::jsonb, 2, 3, 'The group included Blackface and Faze.', 'https://en.wikipedia.org/wiki/Plantashun_Boiz', 'live'),
  ('baf58c0a-5b70-5c08-9036-a0721472a8fd', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which group recorded ''Sakomo''?', '["Plantashun Boiz","Junior and Pretty","The Remedies","Styl-Plus"]'::jsonb, 2, 3, 'The Remedies were Eedris Abdulkareem, Tony Tetuila and Eddy Montana.', 'https://en.wikipedia.org/wiki/The_Remedies', 'live'),
  ('7f130f97-a43e-5d65-b4fa-c634f473aa61', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Styl-Plus is best known for which love song?', '["African Queen","Olufunmi","Kokoroko","Ihe Neme"]'::jsonb, 1, 3, 'Styl-Plus formed in Abuja.', 'https://en.wikipedia.org/wiki/Styl-Plus', 'live'),
  ('90776342-b0bb-5a3f-81df-aeb0124b34e3', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which musician performs in a mask and is known as Lagbaja?', '["Femi Kuti","Tony Allen","Sound Sultan","Bisade Ologunde"]'::jsonb, 3, 3, 'Lagbaja means ''nobody in particular'' in Yoruba.', 'https://en.wikipedia.org/wiki/Lagbaja', 'live'),
  ('ca83733d-f551-59e9-8d0b-54954be11aa3', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which drummer co-created Afrobeat with Fela Kuti?', '["Lekan Animashaun","Ginger Baker","Tunde Williams","Tony Allen"]'::jsonb, 3, 3, 'Fela said there would be no Afrobeat without Tony Allen.', 'https://en.wikipedia.org/wiki/Tony_Allen_(musician)', 'live'),
  ('2791c311-1818-5a8b-8763-14dfecb44b38', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Fela''s band in the 1970s was called?', '["Egypt 80","Africa 70","Koola Lobitos","Positive Force"]'::jsonb, 1, 3, 'He renamed it Egypt 80 at the end of the decade.', 'https://en.wikipedia.org/wiki/Fela_Kuti', 'live'),
  ('03372bcf-516c-5a75-87a7-3c16f3362a60', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which of Fela''s sons leads the band Egypt 80 today?', '["Kunle Kuti","Made Kuti","Seun Kuti","Femi Kuti"]'::jsonb, 2, 3, 'Seun began performing with the band as a child.', 'https://en.wikipedia.org/wiki/Seun_Kuti', 'live'),
  ('bf132ab0-f7f1-51e0-9d4d-750ba0408539', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Fela Kuti''s 1976 song criticising the military is titled?', '["Shakara","Zombie","Gentleman","Lady"]'::jsonb, 1, 3, 'The army raided Kalakuta Republic soon after.', 'https://en.wikipedia.org/wiki/Zombie_(album)', 'live'),
  ('7220b4cd-beb8-581d-bf06-b201f73124d6', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'The Broadway musical about Fela Kuti''s life is called?', '["The Black President","Kalakuta","Fela!","Afrobeat Man"]'::jsonb, 2, 3, 'Fela! won three Tony Awards in 2010.', 'https://en.wikipedia.org/wiki/Fela!', 'live'),
  ('a5dd6e2e-7ea0-5142-b33c-d62386f4be00', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Asa, the singer of ''Jailer'', was born in which country?', '["United Kingdom","Nigeria","France","Benin"]'::jsonb, 2, 3, 'Asa''s parents are Nigerian; she grew up in Lagos.', 'https://en.wikipedia.org/wiki/Asa_(musician)', 'live'),
  ('032ccd60-f619-557a-afb2-c21a4e5e6c61', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Victor Uwaifo''s most famous highlife song is?', '["Baby Jowo","Joromi","Osondi Owendi","Sawale"]'::jsonb, 1, 3, 'Uwaifo was also a sculptor and Edo State commissioner.', 'https://en.wikipedia.org/wiki/Victor_Uwaifo', 'live'),
  ('34cd6001-2f23-55c9-a21c-1ee4c6b4a332', '47139ef4-9c94-5d32-a05b-03686b39cf39', '''Osondi Owendi'' is a classic by which highlife legend?', '["Celestine Ukwu","Oliver De Coque","Rex Lawson","Osita Osadebe"]'::jsonb, 3, 3, 'Osadebe was one of Igbo highlife''s biggest stars.', 'https://en.wikipedia.org/wiki/Stephen_Osita_Osadebe', 'live'),
  ('39803e11-dead-554e-88ef-35e195dc1c4c', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which Nigerian singer, born in Ibadan, won the Grammy for Best New Artist in 1986 with her band?', '["Nneka","Asa","Onyeka Onwenu","Sade Adu"]'::jsonb, 3, 3, 'Sade''s full name is Helen Folasade Adu.', 'https://en.wikipedia.org/wiki/Sade_(singer)', 'live'),
  ('0fb4d910-43bb-5dfd-bb87-aea3f73b9bac', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which singer, nicknamed the ''Elegant Stallion'', released ''One Love''?', '["Christy Essien-Igbokwe","Mary Afi Usuah","Stella Monye","Onyeka Onwenu"]'::jsonb, 3, 3, 'Onyeka Onwenu was also a journalist and politician.', 'https://en.wikipedia.org/wiki/Onyeka_Onwenu', 'live'),
  ('73db7a77-2707-5731-9180-1ff985c02459', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which 1989 Shina Peters album launched the ''Afro-jùjú'' craze?', '["Dancing Time","Ace","Experience","Shinamania"]'::jsonb, 1, 3, 'Ace made Shina Peters a national superstar.', 'https://en.wikipedia.org/wiki/Shina_Peters', 'live'),
  ('5d1b79fe-fa0a-5d77-8fda-0b7b1b6e4bfb', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Rema''s ''Calm Down'' was the first song by an African lead artist to reach how many Spotify streams?', '["500 million","2 billion","250 million","1 billion"]'::jsonb, 3, 4, 'It crossed one billion streams in 2023.', 'https://en.wikipedia.org/wiki/Calm_Down_(Rema_song)', 'live'),
  ('69603d06-b80a-5a6e-9a03-e22c748c7473', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Tems won the 2025 Grammy for Best African Music Performance with which song?', '["Love Me JeJe","Me & U","Higher","Free Mind"]'::jsonb, 0, 4, 'Love Me JeJe interpolates Seyi Sodimu''s 1997 hit.', 'https://en.wikipedia.org/wiki/Tems', 'live'),
  ('81d746a1-e01b-5e3b-9a85-196b52bb3102', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Who won the first Grammy for Best African Music Performance in 2024?', '["Burna Boy","Tyla","Davido","Ayra Starr"]'::jsonb, 1, 4, 'Tyla, from South Africa, won with ''Water''.', 'https://en.wikipedia.org/wiki/Grammy_Award_for_Best_African_Music_Performance', 'live'),
  ('0fd6f107-93db-5257-b84e-b429d6ed1f15', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Burna Boy''s 2018 hit ''Ye'' appeared on which album?', '["African Giant","L.I.F.E","Outside","Redemption"]'::jsonb, 2, 4, 'Many listeners confused it with Kanye West''s album ''Ye'' released the same year.', 'https://en.wikipedia.org/wiki/Ye_(Burna_Boy_song)', 'live'),
  ('c7954347-903b-509a-ae3b-fda50af45fac', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Davido''s debut album, released in 2012, is titled?', '["Son of Mercy","Omo Baba Olowo","A Good Time","The Baddest"]'::jsonb, 1, 4, 'The title means ''son of a rich man'' in Yoruba.', 'https://en.wikipedia.org/wiki/Omo_Baba_Olowo', 'live'),
  ('88e0ffd2-97c2-5e21-aaca-5b19f79b6329', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Wande Coal''s debut album (2009) is titled?', '["Realms","Mushin 2 Mo''Hits","Black Diamond","Wanted"]'::jsonb, 1, 4, 'It is often ranked among the best Nigerian albums of its decade.', 'https://en.wikipedia.org/wiki/Mushin_2_Mo%27Hits', 'live'),
  ('122b3713-128f-5385-abb9-b76180d46b97', '47139ef4-9c94-5d32-a05b-03686b39cf39', '9ice''s 2008 album featuring ''Gongo Aso'' is called?', '["Certificate","Gongo Aso","Bashorun Gaa","Tradition"]'::jsonb, 1, 4, 'Gongo Aso won multiple Headies awards.', 'https://en.wikipedia.org/wiki/9ice', 'live'),
  ('7d25663f-db78-59ce-a83a-24bc5d1b5cd1', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which highlife musician recorded ''Baby Jowo''?', '["Bobby Benson","Rex Lawson","Victor Olaiya","E.T. Mensah"]'::jsonb, 2, 4, 'Olaiya was known as ''the Evil Genius of Highlife''.', 'https://en.wikipedia.org/wiki/Victor_Olaiya', 'live'),
  ('baf7ff72-9bf5-5daf-8d2b-0e24f28f4d58', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Christy Essien-Igbokwe was known by which title?', '["Mama Africa","Golden Voice","Lady of Songs","Queen of Highlife"]'::jsonb, 2, 4, 'Her hits include ''Seun Rere''.', 'https://en.wikipedia.org/wiki/Christy_Essien-Igbokwe', 'live'),
  ('96099f71-d2a0-5c1a-9d21-d84860da0a1e', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Ice Prince''s 2010 breakout hit was?', '["Gimme Dat","Superstar","Aboki","Oleku"]'::jsonb, 3, 4, 'Ice Prince was signed to Chocolate City.', 'https://en.wikipedia.org/wiki/Ice_Prince', 'live'),
  ('c4645046-b353-5e8c-9cec-acb1a2bb983c', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which Hausa instrument is a long metal trumpet used in royal ceremonies?', '["Goje","Kakaki","Algaita","Kalangu"]'::jsonb, 1, 4, 'The kakaki can be over three metres long.', 'https://en.wikipedia.org/wiki/Kakaki', 'live'),
  ('966ea52b-bb60-51b2-a863-c69a9e3a3f11', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'The goje is a traditional Hausa…', '["One- or two-string fiddle","Metal bell","Xylophone","Clay drum"]'::jsonb, 0, 4, 'It is played with a bow, often with a calabash body.', 'https://en.wikipedia.org/wiki/Goje', 'live'),
  ('81cea4ed-44be-5247-a590-97ce6abd35a8', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'The ogene is an Igbo instrument made of…', '["Animal skin","Metal (it is a gong/bell)","Gourd and beads","Clay"]'::jsonb, 1, 4, 'It is struck with a stick to keep the beat.', 'https://en.wikipedia.org/wiki/Ogene', 'live'),
  ('c715f98c-4153-5a3e-9415-9e27aa2364f3', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which Kcee song popularised the ''Ojapiano'' sound in 2023?', '["Limpopo","Pullover","Erima","Ojapiano"]'::jsonb, 3, 4, 'It blends amapiano with the Igbo oja flute.', 'https://en.wikipedia.org/wiki/Kcee', 'live'),
  ('2c7f3088-2d82-59e2-93ad-4241c0939dc1', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'The ''Zanku'' (Legwork) dance was popularised by which artist?', '["Poco Lee","Naira Marley","Olamide","Zlatan"]'::jsonb, 3, 4, 'Zanku took over parties and social media in 2018–2019.', 'https://en.wikipedia.org/wiki/Zlatan_(musician)', 'live'),
  ('054edcb7-6f03-592b-bf4d-1f8185dea2f6', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'In 2018 Tiwa Savage became the first woman to win which award?', '["BET Best International Act","MTV EMA Best African Act","Grammy Best World Music","Headies Next Rated"]'::jsonb, 1, 4, 'She won it at the MTV Europe Music Awards in Bilbao.', 'https://en.wikipedia.org/wiki/Tiwa_Savage', 'in_review'),
  ('2a427e43-1566-5e79-999b-2bb86e4b5740', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Iyanya rose to fame after winning which TV talent show in 2008?', '["Star Quest","Nigerian Idol","The Voice Nigeria","MTN Project Fame West Africa"]'::jsonb, 3, 4, 'His later hit ''Kukere'' made him a household name.', 'https://en.wikipedia.org/wiki/Iyanya', 'in_review'),
  ('d743fb35-e2aa-50cf-b160-e54b38954e7a', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Davido''s hit ''If'' (2017) was produced by which artist?', '["Kiddominant","Shizzi","Sarz","Tekno"]'::jsonb, 3, 4, 'Tekno is also a singer known for ''Pana''.', 'https://en.wikipedia.org/wiki/If_(Davido_song)', 'live'),
  ('a6701131-3cdf-520a-8077-fb3dd7628742', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Before Afrobeat, Fela Kuti led a highlife-jazz band called?', '["Koola Lobitos","Nigeria 70","Highlife Rakers","Africa 70"]'::jsonb, 0, 5, 'Koola Lobitos was formed in the early 1960s.', 'https://en.wikipedia.org/wiki/Fela_Kuti', 'live'),
  ('6a2ddbfe-aa82-571b-a142-9a7412482ca5', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which Fela Kuti song title is a Pidgin saying meaning nothing can fight water?', '["Confusion","Water No Get Enemy","Opposite People","Expensive Shit"]'::jsonb, 1, 5, 'Fela titled many songs in Nigerian Pidgin so ordinary people could relate.', 'https://en.wikipedia.org/wiki/Fela_Kuti', 'live'),
  ('897dea65-9631-580d-a072-b55dd2799386', '47139ef4-9c94-5d32-a05b-03686b39cf39', '''Sawale'' is a classic by which Kalabari highlife star?', '["Celestine Ukwu","Cardinal Rex Lawson","Prince Nico Mbarga","Oliver De Coque"]'::jsonb, 1, 5, 'Rex Lawson was one of the biggest highlife stars of the 1960s.', 'https://en.wikipedia.org/wiki/Rex_Lawson', 'live'),
  ('65781629-692e-5099-9d03-3962197ecba6', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Prince Nico Mbarga''s 1976 highlife hit, one of Africa''s best-selling singles, is?', '["Sweet Mother","Joromi","Ijele","Osondi Owendi"]'::jsonb, 0, 5, 'Mbarga was of Nigerian-Cameroonian parentage.', 'https://en.wikipedia.org/wiki/Sweet_Mother', 'live'),
  ('fe239422-153e-568a-bfc8-128ca488ad49', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'King Sunny Adé''s 1983 album ''Synchro System'' earned what?', '["A Mercury Prize","A Grammy nomination","A Brit Award","An Oscar nomination"]'::jsonb, 1, 5, 'He was among the first Africans nominated for a Grammy.', 'https://en.wikipedia.org/wiki/King_Sunny_Ad%C3%A9', 'live'),
  ('c6d12bff-1dc9-59d0-8d2f-243ed8c77bfa', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which apala legend is famed for songs like ''Pansa Pansa''?', '["Ayinla Omowura","Dauda Epo-Akara","Haruna Ishola","Yusuf Olatunji"]'::jsonb, 2, 5, 'Haruna Ishola was one of apala''s biggest stars.', 'https://en.wikipedia.org/wiki/Haruna_Ishola', 'in_review'),
  ('586b6c0e-3910-5678-a737-e5cccd7156ae', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Mr Eazi coined which term for his blend of Ghanaian and Nigerian sounds?', '["Banku music","Afro-soul","Afro-fusion","Afro-swing"]'::jsonb, 0, 5, 'Mr Eazi also founded the emPawa Africa talent programme.', 'https://en.wikipedia.org/wiki/Mr_Eazi', 'live'),
  ('d1c7398a-7db0-5730-ac27-cc239eae08d4', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Burna Boy describes his own musical style as?', '["Afro-swing","Afro-fusion","Banku","Afro-rave"]'::jsonb, 1, 5, 'He blends Afrobeats, dancehall, reggae and hip hop.', 'https://en.wikipedia.org/wiki/Burna_Boy', 'live'),
  ('6f8061db-97f3-5a4a-bae2-82617f3098c4', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Rema calls his signature sound?', '["Afro-rave","Afro-trap","Afro-life","Afro-fusion"]'::jsonb, 0, 5, 'His debut album is Rave & Roses.', 'https://en.wikipedia.org/wiki/Rema_(musician)', 'live'),
  ('8314c895-b719-5027-84e8-cf489b156a75', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Which Nigerian singer''s 2010 debut ''Victim of Truth'' includes ''Heartbeat''?', '["Nneka","Omawumi","Asa","Waje"]'::jsonb, 0, 5, 'Nneka was born in Warri to a Nigerian father and German mother.', 'https://en.wikipedia.org/wiki/Nneka_(singer)', 'live'),
  ('8678ed2e-7104-5e81-b613-d8bfd0124ca5', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'The spelling ''Afrobeats'' (with an s) was popularised around 2011 by which UK DJ?', '["DJ Abrantee","Tim Westwood","DJ Edu","DJ Spinall"]'::jsonb, 0, 5, 'The plural name covers a broader pop sound than Fela''s Afrobeat.', 'https://en.wikipedia.org/wiki/Afrobeats', 'in_review'),
  ('a0cab760-596c-5af6-a98a-c3ad01b4cfd1', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Celestine Ukwu, celebrated for philosophical lyrics, played which genre?', '["Jùjú","Apala","Highlife","Fuji"]'::jsonb, 2, 5, 'Celestine Ukwu was a leading Igbo highlife musician of the 1960s and 70s.', 'https://en.wikipedia.org/wiki/Celestine_Ukwu', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('09f5e6a1-618f-5c20-b120-3bc88b98e3b0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'What is the nickname of Nigeria''s men''s national football team?', '["Flying Eagles","Black Stars","Super Eagles","Super Falcons"]'::jsonb, 2, 1, 'Before the late 1980s the team was called the Green Eagles.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('e980731a-2fde-51eb-b92b-e60091260541', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'What is the nickname of Nigeria''s women''s national football team?', '["D''Tigress","Super Eagles","Golden Eaglets","Super Falcons"]'::jsonb, 3, 1, 'The Super Falcons are Africa''s most successful women''s team.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_football_team', 'live'),
  ('45f268b6-2a2f-5f3f-afdd-08c218582883', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s U-17 men''s team is nicknamed?', '["Golden Eaglets","Dream Team","Flying Eagles","Young Falcons"]'::jsonb, 0, 1, 'The Golden Eaglets have won the U-17 World Cup a record five times.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-17_football_team', 'live'),
  ('703d0bc4-1a39-5a79-840d-fe4e52886c7e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which midfielder was nicknamed ''Jay-Jay''?', '["Sunday Oliseh","Augustine Okocha","Mikel John Obi","Nwankwo Kanu"]'::jsonb, 1, 1, 'Fans said he was ''so good they named him twice''.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
  ('50722949-9717-594d-b5cb-1cf69c7c2645', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian striker won the 2022–23 Serie A title with Napoli?', '["Kelechi Iheanacho","Victor Osimhen","Samuel Chukwueze","Ademola Lookman"]'::jsonb, 1, 1, 'Osimhen was Serie A''s top scorer that season.', 'https://en.wikipedia.org/wiki/Victor_Osimhen', 'live'),
  ('cf34cc6c-00fd-5ae4-bae5-cb32e9265a9c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which year did Nigeria play at its first FIFA World Cup?', '["1982","1998","1990","1994"]'::jsonb, 3, 1, 'The tournament was held in the United States.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_FIFA_World_Cup', 'live'),
  ('cbfab68e-bb6f-588a-a3f3-f1999da83f63', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria won Olympic football gold at which Games?', '["Beijing 2008","Barcelona 1992","Sydney 2000","Atlanta 1996"]'::jsonb, 3, 1, 'Nigeria was the first African nation to win Olympic football gold.', 'https://en.wikipedia.org/wiki/Football_at_the_1996_Summer_Olympics', 'live'),
  ('fff38bb6-8ad0-5658-bdad-1869da25aac6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian-born basketball legend won two NBA titles with the Houston Rockets?', '["Hakeem Olajuwon","Giannis Antetokounmpo","Dikembe Mutombo","Joel Embiid"]'::jsonb, 0, 1, 'Olajuwon was born and raised in Lagos.', 'https://en.wikipedia.org/wiki/Hakeem_Olajuwon', 'live'),
  ('2fcb644b-cd08-5056-9820-b6d07edb9190', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which UFC champion is nicknamed ''The Nigerian Nightmare''?', '["Sodiq Yusuff","Kamaru Usman","Israel Adesanya","Francis Ngannou"]'::jsonb, 1, 1, 'Usman held the UFC welterweight title.', 'https://en.wikipedia.org/wiki/Kamaru_Usman', 'live'),
  ('36e6cbe3-b804-5148-a2f1-f34f6580d2bf', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Israel Adesanya, the UFC middleweight champion, is nicknamed?', '["The Last Stylebender","Iron Mike","The Predator","The Nigerian Nightmare"]'::jsonb, 0, 1, 'Adesanya was born in Lagos.', 'https://en.wikipedia.org/wiki/Israel_Adesanya', 'live'),
  ('05e62ed3-d06f-5490-b519-564a9d2f4cab', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Tobi Amusan holds the world record in which event?', '["100m hurdles","400m hurdles","200m","Long jump"]'::jsonb, 0, 1, 'She set the record at the 2022 World Championships.', 'https://en.wikipedia.org/wiki/Tobi_Amusan', 'live'),
  ('7ffa7695-a676-5955-956e-337b06005132', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which boxer of Nigerian heritage won Olympic gold at London 2012 and became world heavyweight champion?', '["Efe Ajagba","Dillian Whyte","Anthony Joshua","Samuel Peter"]'::jsonb, 2, 1, 'Joshua''s family is from Sagamu, Ogun State.', 'https://en.wikipedia.org/wiki/Anthony_Joshua', 'live'),
