  ('92d19298-bb16-5ce0-b0a6-daaa9a8aca0a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria beat which team in the 1994 AFCON final?', '["Mali","Zambia","Ghana","Ivory Coast"]'::jsonb, 1, 4, 'Emmanuel Amunike scored both goals in a 2–1 win.', 'https://en.wikipedia.org/wiki/1994_African_Cup_of_Nations', 'live'),
  ('6a977c2e-3e05-5225-a810-045554b32511', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'How many U-17 World Cup titles have Nigeria''s Golden Eaglets won?', '["2","4","5","3"]'::jsonb, 2, 4, 'They won in 1985, 1993, 2007, 2013 and 2015.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-17_football_team', 'live'),
  ('c0453f1a-aec8-5f5f-a2d2-7a82d1af7104', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria failed to qualify for the 2022 World Cup after a play-off against which country?', '["Ghana","Tunisia","Egypt","Cameroon"]'::jsonb, 0, 4, 'Ghana went through on away goals after 0–0 and 1–1 draws.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('96c3a22d-8d2a-568e-972e-43617e797a6e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who was the Super Eagles'' head coach at the 2023 AFCON?', '["Gernot Rohr","Finidi George","José Peseiro","Augustine Eguavoen"]'::jsonb, 2, 4, 'The Portuguese coach guided Nigeria to the final.', 'https://en.wikipedia.org/wiki/Jos%C3%A9_Peseiro', 'live'),
  ('ed379b0f-becf-5c6d-9565-c6f56ced95a3', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian was the top scorer at the 2019 AFCON?', '["Odion Ighalo","Alex Iwobi","Samuel Kalu","Ahmed Musa"]'::jsonb, 0, 4, 'Ighalo scored five goals as Nigeria finished third.', 'https://en.wikipedia.org/wiki/Odion_Ighalo', 'live'),
  ('53b23b1d-495b-5ee8-8e83-2665d00e9930', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Moshood Abiola National Stadium is in which city?', '["Lagos","Ibadan","Abuja","Uyo"]'::jsonb, 2, 4, 'It was renamed in 2019 from the National Stadium, Abuja.', 'https://en.wikipedia.org/wiki/Moshood_Abiola_National_Stadium', 'live'),
  ('76b3793f-e10c-521a-b673-76977907f2c7', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which stadium in Uyo has become the Super Eagles'' main home ground?', '["Godswill Akpabio International Stadium","Ahmadu Bello Stadium","U.J. Esuene Stadium","Teslim Balogun Stadium"]'::jsonb, 0, 4, 'It is nicknamed the ''Nest of Champions''.', 'https://en.wikipedia.org/wiki/Godswill_Akpabio_International_Stadium', 'live'),
  ('6fc39569-38c3-5296-ab25-f41f178529ee', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s first-ever Olympic medal was won in which sport?', '["Boxing","Weightlifting","Football","Athletics"]'::jsonb, 0, 4, 'Nojim Maiyegun won bronze at Tokyo 1964.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_Olympics', 'live'),
  ('a4e35cc7-5858-5d2d-adc7-c33155064f13', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian goalkeeper went 1,000+ minutes without conceding in Ligue 1 for Lille?', '["Peter Rufai","Austin Ejide","Vincent Enyeama","Carl Ikeme"]'::jsonb, 2, 4, 'He was named African Goalkeeper of the Year in that era.', 'https://en.wikipedia.org/wiki/Vincent_Enyeama', 'in_review'),
  ('46158b96-345c-566e-8160-ac1671c8214b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Taribo West played for both Inter Milan and which other Milan club?', '["AC Milan","Atalanta","Monza","Como"]'::jsonb, 0, 4, 'He was known for his colourful braided hairstyles.', 'https://en.wikipedia.org/wiki/Taribo_West', 'live'),
  ('478e55f6-dd6f-594e-bbf3-4c773a6dc4e4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Daniel Amokachi starred for which English club in the mid-1990s?', '["Leeds United","Newcastle United","Everton","Aston Villa"]'::jsonb, 2, 4, 'He scored twice in Everton''s 1995 FA Cup semi-final.', 'https://en.wikipedia.org/wiki/Daniel_Amokachi', 'live'),
  ('29556912-2a6f-5241-b5d3-9ef1ad9079d2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Jay-Jay Okocha captained which English club?', '["Portsmouth","Bolton Wanderers","Hull City","West Brom"]'::jsonb, 1, 4, 'He joined Bolton from Paris Saint-Germain in 2002.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
  ('a71ae706-ff51-5441-9acf-9dae80fde2d0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s women''s basketball team won the AfroBasket title in 2017, 2019, 2021 and which year?', '["2015","2023","2013","2011"]'::jsonb, 1, 4, 'D''Tigress dominated African women''s basketball in that era.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_basketball_team', 'live'),
  ('0cd3eebc-fe9b-59e1-8a19-1b7f6ecccc49', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'At Paris 2024, D''Tigress became the first African team to reach which stage of the Olympic basketball tournament?', '["Quarter-finals","Group stage","Semi-finals","Final"]'::jsonb, 0, 4, 'They beat Australia and Canada in the group stage.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_basketball_team', 'in_review'),
  ('156ed311-c106-5d39-bfe8-c0576e7689d6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s men''s 4x400m relay team was upgraded to gold for which Olympics?', '["Athens 2004","Sydney 2000","Atlanta 1996","Beijing 2008"]'::jsonb, 1, 4, 'The US team was later disqualified over a doping case.', 'https://en.wikipedia.org/wiki/Athletics_at_the_2000_Summer_Olympics_%E2%80%93_Men%27s_4_%C3%97_400_metres_relay', 'in_review'),
  ('9f48c438-5f1b-5727-9198-510c71d8b1cc', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian club won the African Cup Winners'' Cup in 1976?', '["Shooting Stars","Enyimba","Rangers International","Bendel Insurance"]'::jsonb, 0, 4, 'Shooting Stars are based in Ibadan.', 'https://en.wikipedia.org/wiki/Shooting_Stars_S.C.', 'in_review'),
  ('0a3590f5-2e7e-56e9-a80a-2dfa22badec0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Rangers International FC is based in which city?', '["Aba","Onitsha","Enugu","Owerri"]'::jsonb, 2, 4, 'Rangers are nicknamed ''The Flying Antelopes''.', 'https://en.wikipedia.org/wiki/Rangers_International_F.C.', 'live'),
  ('fd17509f-9d39-58bf-8c87-ad356e1e5d33', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Before ''Super Eagles'', what was Nigeria''s national team called?', '["Lone Stars","Green Eagles","Desert Warriors","Red Devils"]'::jsonb, 1, 5, 'The team was called the Red Devils in its early years before becoming the Green Eagles.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'in_review'),
  ('51a61ecd-8ab0-5c75-bcbb-b5b6a0bb1b6f', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Stephen Keshi and which Egyptian are the only two men to win AFCON as player and coach?', '["Mahmoud El-Gohary","Hassan Shehata","Mohamed Aboutrika","Hossam Hassan"]'::jsonb, 0, 5, 'Keshi won in 1994 as a player and 2013 as coach.', 'https://en.wikipedia.org/wiki/Stephen_Keshi', 'live'),
  ('96719847-245f-5a94-9fb5-9dcc15134f47', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which country did Nigeria win the inaugural U-16 world title in 1985?', '["China","Scotland","Japan","Canada"]'::jsonb, 0, 5, 'The tournament later became the U-17 World Cup.', 'https://en.wikipedia.org/wiki/1985_FIFA_U-16_World_Championship', 'live'),
  ('9f35c458-431c-5cd9-bafb-cc57897c75ab', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which city hosted the 2nd All-Africa Games in 1973?', '["Kaduna","Ibadan","Lagos","Abuja"]'::jsonb, 2, 5, 'The Games were held at the National Stadium, Surulere.', 'https://en.wikipedia.org/wiki/1973_All-Africa_Games', 'live'),
  ('92ba4b6d-57fd-5065-9737-b86e0a864b7e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who won Nigeria''s first Olympic medal, a bronze in boxing in 1964?', '["Nojim Maiyegun","Dick Tiger","Hogan Bassey","Isaac Ikhouria"]'::jsonb, 0, 5, 'Maiyegun won bronze in the light-middleweight division in Tokyo.', 'https://en.wikipedia.org/wiki/Nojim_Maiyegun', 'live'),
  ('0dc3c85a-05e9-5c6f-b545-75ce93d1e516', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s 1996 Olympic squad included which future Chelsea defender, a teenage star then?', '["Uche Okechukwu","Joseph Yobo","Celestine Babayaro","Taribo West"]'::jsonb, 2, 5, 'Babayaro was known for his somersault celebrations.', 'https://en.wikipedia.org/wiki/Celestine_Babayaro', 'live'),
  ('4c21c2ec-f86a-5321-845b-3f78683f3ef4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored the golden goal against Brazil in the 1996 Olympic semi-final?', '["Tijani Babangida","Emmanuel Amunike","Nwankwo Kanu","Victor Ikpeba"]'::jsonb, 2, 5, 'Kanu had also scored Nigeria''s equaliser in the 90th minute.', 'https://en.wikipedia.org/wiki/Football_at_the_1996_Summer_Olympics', 'live'),
  ('4b506465-d1b9-5d3b-bd3a-89808ba1f80c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s Flying Eagles reached the FIFA U-20 World Cup final in 1989 and which other year?', '["1999","2005","2011","2015"]'::jsonb, 1, 5, 'In 2005 they lost the final to an Argentina side featuring Lionel Messi.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-20_football_team', 'live'),
  ('31e06b7b-f9ac-5750-a288-c702d8fc62d2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Malian-French coach was appointed Super Eagles head coach in January 2025?', '["Claude Le Roy","Paul Put","Hervé Renard","Éric Chelle"]'::jsonb, 3, 5, 'He previously coached Mali.', 'https://en.wikipedia.org/wiki/%C3%89ric_Chelle', 'live'),
  ('03cbfc35-dec2-5867-b59c-7995dc9ace30', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria hosted which FIFA youth tournament in 2009?', '["U-20 World Cup","Women''s U-20 World Cup","U-17 World Cup","Club World Cup"]'::jsonb, 2, 5, 'Nigeria reached the final but lost to Switzerland.', 'https://en.wikipedia.org/wiki/2009_FIFA_U-17_World_Cup', 'live'),
  ('3dc9adf8-e9c6-563e-89f8-7a88eab834ae', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria hosted the FIFA World Youth Championship (U-20) in which year?', '["1989","1999","1995","2003"]'::jsonb, 1, 5, 'Spain won the tournament, with matches in Lagos, Kaduna, Enugu and elsewhere.', 'https://en.wikipedia.org/wiki/1999_FIFA_World_Youth_Championship', 'live'),
  ('3065e718-5246-5648-8c8e-619bb984a75e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s first Africa Cup of Nations appearance was in which year?', '["1976","1980","1963","1957"]'::jsonb, 2, 5, 'Nigeria were knocked out in the group stage in Ghana.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'in_review')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('db0cf9f4-e266-5cf2-87f1-bf8be5a4b3f3', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'On what date did Nigeria gain independence?', '["29 May 1960","1 January 1963","12 June 1960","1 October 1960"]'::jsonb, 3, 1, 'Independence Day is celebrated every 1 October.', 'https://en.wikipedia.org/wiki/Nigeria', 'live'),
  ('02b35bcd-e03f-5bc7-b745-d12e4fc45b4f', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which city replaced Lagos as Nigeria''s capital in 1991?', '["Abuja","Ibadan","Kaduna","Lokoja"]'::jsonb, 0, 1, 'The move became official on 12 December 1991.', 'https://en.wikipedia.org/wiki/Abuja', 'live'),
  ('2802ded4-ae98-5f4f-8448-e9142cf8401b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'What are the colours of the Nigerian flag?', '["Green, white, green","White, green, white","Green, white, red","Green, yellow, green"]'::jsonb, 0, 1, 'Green stands for the land; white for peace.', 'https://en.wikipedia.org/wiki/Flag_of_Nigeria', 'live'),
  ('898b4009-34b5-583e-a5d7-7455f51c44ca', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who designed the Nigerian flag?', '["Herbert Macaulay","Flora Shaw","Michael Taiwo Akinkunmi","Nnamdi Azikiwe"]'::jsonb, 2, 1, 'He was a student in London when he submitted the design in 1959.', 'https://en.wikipedia.org/wiki/Taiwo_Akinkunmi', 'live'),
  ('7312a49c-88d9-5971-a4f3-b68d45875320', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was Nigeria''s first Prime Minister?', '["Abubakar Tafawa Balewa","Ahmadu Bello","Obafemi Awolowo","Nnamdi Azikiwe"]'::jsonb, 0, 1, 'Balewa was called the ''Golden Voice of Africa''.', 'https://en.wikipedia.org/wiki/Abubakar_Tafawa_Balewa', 'live'),
  ('8d904543-6be5-5f62-a537-263d5773c605', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was Nigeria''s first President?', '["Olusegun Obasanjo","Nnamdi Azikiwe","Abubakar Tafawa Balewa","Shehu Shagari"]'::jsonb, 1, 1, 'Azikiwe became President when Nigeria became a republic in 1963.', 'https://en.wikipedia.org/wiki/Nnamdi_Azikiwe', 'live'),
  ('ad22abb4-6fbe-56ef-ab36-152e6652b9f2', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'How many states does Nigeria have?', '["38","37","30","36"]'::jsonb, 3, 1, 'Plus the Federal Capital Territory, Abuja.', 'https://en.wikipedia.org/wiki/States_of_Nigeria', 'live'),
  ('437616dd-1350-5fb9-a125-8cd8a7188005', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'What is Nigeria''s currency?', '["Dalasi","Shilling","Naira","Cedi"]'::jsonb, 2, 1, 'The naira replaced the Nigerian pound in 1973.', 'https://en.wikipedia.org/wiki/Nigerian_naira', 'live'),
  ('306dddc9-20bc-5af1-b7b2-b57f586d7452', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'One naira is divided into 100…', '["Kobo","Shillings","Pesewas","Cents"]'::jsonb, 0, 1, 'Kobo coins are rarely used today.', 'https://en.wikipedia.org/wiki/Nigerian_naira', 'live'),
  ('db7730a2-a534-5e13-afd8-e85266138551', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Nigerian won the Nobel Prize in Literature in 1986?', '["Wole Soyinka","Chinua Achebe","Chimamanda Ngozi Adichie","Ben Okri"]'::jsonb, 0, 1, 'He was the first African to win the literature prize.', 'https://en.wikipedia.org/wiki/Wole_Soyinka', 'live'),
  ('d6e04d75-4369-5adb-a001-3edaf4e7d6d9', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'What is the name of the presidential residence in Abuja?', '["Aso Rock Presidential Villa","Dodan Barracks","Zuma Villa","State House Marina"]'::jsonb, 0, 1, 'Dodan Barracks in Lagos served as the seat of government earlier.', 'https://en.wikipedia.org/wiki/Aso_Rock_Presidential_Villa', 'live'),
  ('ebae74a7-1efa-5ffc-b99d-66af90a3b79d', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Nigeria''s Democracy Day is celebrated on which date?', '["12 June","29 May","15 January","1 October"]'::jsonb, 0, 1, 'It moved from 29 May to 12 June from 2019.', 'https://en.wikipedia.org/wiki/Democracy_Day_(Nigeria)', 'live'),
  ('72815b4b-33cf-5c77-821a-d39cc9d6ef7d', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who is credited with suggesting the name ''Nigeria''?', '["Frederick Lugard","Mary Slessor","Flora Shaw","Mungo Park"]'::jsonb, 2, 1, 'She proposed it in an 1897 article in The Times.', 'https://en.wikipedia.org/wiki/Flora_Shaw', 'live'),
  ('1d5139f4-dfa1-566b-981f-fde2662263b6', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who amalgamated the Northern and Southern Protectorates in 1914?', '["George Goldie","Hugh Clifford","Arthur Richards","Frederick Lugard"]'::jsonb, 3, 1, 'Lugard became the first Governor-General of Nigeria.', 'https://en.wikipedia.org/wiki/Frederick_Lugard,_1st_Baron_Lugard', 'live'),
  ('28d4d26b-af8a-5e37-a5fb-c289225d019b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Nigeria''s national motto is ''Unity and Faith, Peace and…''?', '["Progress","Strength","Prosperity","Justice"]'::jsonb, 0, 1, 'The motto appears on the coat of arms.', 'https://en.wikipedia.org/wiki/Coat_of_arms_of_Nigeria', 'live'),
  ('7b7d2cc2-4153-5bda-91d8-08b044305a9d', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which national anthem did Nigeria readopt in 2024?', '["Land of Our Fathers","One Nigeria","Nigeria, We Hail Thee","Arise, O Compatriots"]'::jsonb, 2, 1, '''Nigeria, We Hail Thee'' was first used at independence in 1960.', 'https://en.wikipedia.org/wiki/Nigeria,_We_Hail_Thee', 'live'),
  ('0fee55b5-be80-5c7b-870f-2245aa9ee9b8', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The ''Y'' shape on Nigeria''s coat of arms represents which two rivers?', '["Niger and Benue","Niger and Kaduna","Ogun and Osun","Benue and Cross River"]'::jsonb, 0, 1, 'The rivers meet at Lokoja.', 'https://en.wikipedia.org/wiki/Coat_of_arms_of_Nigeria', 'live'),
  ('aa981a59-045a-51e6-a8d9-8aa290586c2b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which ancient warrior queen ruled Zazzau (Zaria)?', '["Queen Idia","Queen Amina","Queen Kambasa","Queen Moremi"]'::jsonb, 1, 1, 'She is remembered for building defensive walls around cities.', 'https://en.wikipedia.org/wiki/Amina', 'live'),
  ('7eec65f0-26d8-509d-a291-c31e83433bf3', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Ile-Ife heroine is celebrated for sacrificing her son to save her people?', '["Efunroye Tinubu","Emotan","Inikpi","Moremi Ajasoro"]'::jsonb, 3, 1, 'Her statue stands in Ile-Ife.', 'https://en.wikipedia.org/wiki/Moremi_Ajasoro', 'live'),
  ('40070f81-2fa8-5b2e-83e5-ccb2870aa9ce', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who led the 19th-century jihad that created the Sokoto Caliphate?', '["Muhammad Bello","El-Kanemi","Usman dan Fodio","Ahmadu Bello"]'::jsonb, 2, 1, 'The jihad began in 1804.', 'https://en.wikipedia.org/wiki/Usman_dan_Fodio', 'live'),
  ('9fcfda2a-3887-57c3-a091-c7b865c0d3f7', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'In which year did Nigeria become a republic?', '["1966","1963","1979","1960"]'::jsonb, 1, 2, 'Nigeria became a republic on 1 October 1963.', 'https://en.wikipedia.org/wiki/First_Nigerian_Republic', 'live'),
  ('506bfd6b-006f-5b15-92e7-39094b8da558', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'In which year were the Northern and Southern Protectorates amalgamated?', '["1861","1960","1900","1914"]'::jsonb, 3, 2, 'The amalgamation took effect on 1 January 1914.', 'https://en.wikipedia.org/wiki/Amalgamation_of_Northern_and_Southern_Nigeria', 'live'),
  ('dc86b29c-46ad-599b-b838-07a8b20d151e', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who wrote the Nigerian National Pledge?', '["Benedict Odiase","Lillian Jean Williams","Taiwo Akinkunmi","Felicia Adebola Adeyoyin"]'::jsonb, 3, 2, 'She wrote it in 1976.', 'https://en.wikipedia.org/wiki/Nigerian_National_Pledge', 'live'),
  ('a608eb08-ec77-55d3-81f2-9b05e3b04732', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who wrote the lyrics of ''Nigeria, We Hail Thee''?', '["Lillian Jean Williams","Felicia Adeyoyin","Benedict Odiase","Frances Berda"]'::jsonb, 0, 2, 'Frances Berda composed the music.', 'https://en.wikipedia.org/wiki/Nigeria,_We_Hail_Thee', 'live'),
  ('0be7cf2b-c470-5972-bbd3-0db4b0b1c99d', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which anthem was used from 1978 to 2024?', '["Land of Unity","Arise, O Compatriots","God Bless Nigeria","Nigeria, We Hail Thee"]'::jsonb, 1, 2, 'Its music was composed by the Nigeria Police Band under Benedict Odiase.', 'https://en.wikipedia.org/wiki/Arise,_O_Compatriots', 'live'),
  ('d33201cf-21d7-5d3c-bb1f-622317359dc4', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was the first Premier of the Northern Region?', '["Aminu Kano","Ahmadu Bello","Abubakar Tafawa Balewa","Muhammadu Ribadu"]'::jsonb, 1, 2, 'He held the title Sardauna of Sokoto.', 'https://en.wikipedia.org/wiki/Ahmadu_Bello', 'live'),
  ('a369c888-15f9-5171-a1db-aac0d2b3dc0f', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was the first Premier of the Western Region?', '["Samuel Akintola","Bola Ige","Adekunle Ajasin","Obafemi Awolowo"]'::jsonb, 3, 2, 'He introduced free primary education in the region in 1955.', 'https://en.wikipedia.org/wiki/Obafemi_Awolowo', 'live'),
