  ('c8f1ab7a-e467-515a-93e3-df4f12a8700f', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Margaret Ekpo is remembered as a pioneer of what?', '["Women''s political participation","Nollywood film","Female aviation","Nigerian highlife"]'::jsonb, 0, 4, 'Calabar''s airport is named after her.', 'https://en.wikipedia.org/wiki/Margaret_Ekpo', 'live'),
  ('333557cc-078d-5c58-b28f-3641a036c02b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Nigeria''s 2006 national census counted roughly how many people?', '["200 million","115 million","88 million","140 million"]'::jsonb, 3, 4, 'No full national census has been held since 2006.', 'https://en.wikipedia.org/wiki/Demographics_of_Nigeria', 'in_review'),
