  ('1377fbce-08c6-53bf-ab7a-c9b08304dbb2', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'What is Nigeria''s highest mountain?', '["Idanre Hills","Dimlang","Shere Hills","Chappal Waddi"]'::jsonb, 3, 3, 'Chappal Waddi rises to about 2,419 metres.', 'https://en.wikipedia.org/wiki/Chappal_Waddi', 'live'),
