  ('8ba6d117-fe18-58e2-bbde-332f9af7e61f', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Lake Chad is shared by Nigeria, Niger, Chad and which other country?', '["Sudan","Central African Republic","Mali","Cameroon"]'::jsonb, 3, 3, 'The lake has shrunk dramatically since the 1960s.', 'https://en.wikipedia.org/wiki/Lake_Chad', 'live'),
