  ('4c121a57-8104-5fcd-9d6e-8f6a28b3405e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which Ogun town hosts the colourful Ojude Oba festival?', '["Ijebu-Ode","Abeokuta","Ota","Sagamu"]'::jsonb, 0, 4, 'It is held after Eid al-Adha.', 'https://en.wikipedia.org/wiki/Ojude_Oba_festival', 'live'),
  ('a47cb4ac-377e-5426-8b36-cb82385b5c9e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Durbar festival, with its horse-riding procession, is most associated with which city?', '["Enugu","Calabar","Ibadan","Kano"]'::jsonb, 3, 4, 'Durbars are also held in Katsina, Zaria and Bida.', 'https://en.wikipedia.org/wiki/Durbar_festival', 'live'),
  ('2abc2ddb-fe58-54ff-93f5-d49e56ce3748', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Nigeria''s time zone is…', '["Greenwich Mean Time (UTC+0)","West Africa Time (UTC+1)","East Africa Time (UTC+3)","Central Africa Time (UTC+2)"]'::jsonb, 1, 4, 'Nigeria does not observe daylight saving time.', 'https://en.wikipedia.org/wiki/West_Africa_Time', 'live'),
  ('2301794c-3c01-54a8-9219-d3bf783ee40e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state is the ''Home of Peace'' according to its official slogan?', '["Borno","Gombe","Kwara","Plateau"]'::jsonb, 0, 4, 'Borno''s capital is Maiduguri.', 'https://en.wikipedia.org/wiki/Borno_State', 'in_review'),
