  ('f9f09d39-2667-52be-8c04-d7ae2f2e5804', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state was created from Kaduna State in 1987?', '["Jigawa","Kano","Katsina","Zamfara"]'::jsonb, 2, 5, 'Katsina is home to the ancient Gobarau Minaret.', 'https://en.wikipedia.org/wiki/Katsina_State', 'live'),
