  ('e2148134-edcf-5161-8113-2b90ad4959a4', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Nigeria''s total area is closest to…', '["1.2 million km²","512,000 km²","924,000 km²","650,000 km²"]'::jsonb, 2, 5, 'That''s about four times the size of the United Kingdom.', 'https://en.wikipedia.org/wiki/Nigeria', 'live'),
  ('b3aced04-c20c-5f35-84ec-f5b4b9a2371e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Leboku New Yam Festival is held in which Cross River town?', '["Ikom","Obudu","Ogoja","Ugep"]'::jsonb, 3, 5, 'Leboku celebrates the new yam harvest among the Yakurr people.', 'https://en.wikipedia.org/wiki/Ugep', 'live'),
