  ('ebee6af6-8163-5415-a73e-7f63d415d037', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The River Benue flows into Nigeria from which country?', '["Chad","Niger","Cameroon","Central African Republic"]'::jsonb, 2, 5, 'It rises in the Adamawa Plateau of Cameroon.', 'https://en.wikipedia.org/wiki/Benue_River', 'live'),
