  ('61ef861f-01cd-5c5d-adc3-109347d965b8', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Jewel in the Savannah''?', '["Gombe","Adamawa","Yobe","Bauchi"]'::jsonb, 0, 5, 'Gombe was created from Bauchi State in 1996.', 'https://en.wikipedia.org/wiki/Gombe_State', 'live'),
  ('ccd5a116-1dc7-5ec5-af22-40e9d888bf3f', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Land of Equity''?', '["Zamfara","Jigawa","Sokoto","Kebbi"]'::jsonb, 3, 5, 'Kebbi was created from Sokoto State in 1991.', 'https://en.wikipedia.org/wiki/Kebbi_State', 'in_review')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('5586c099-a1fc-5eaf-9958-1b79d72b46e3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which rice dish sparks friendly ''wars'' between Nigeria and Ghana?', '["Coconut rice","Ofada rice","Fried rice","Jollof rice"]'::jsonb, 3, 1, 'Nigerian party jollof often has a smoky ''bottom pot'' flavour.', 'https://en.wikipedia.org/wiki/Jollof_rice', 'live'),
