  ('a78b1504-950f-5a0d-b120-2c80075fd4a2', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Moi moi is a…', '["Pepper soup","Steamed bean pudding","Fried yam snack","Rice cake"]'::jsonb, 1, 1, 'It is often cooked in leaves or tins.', 'https://en.wikipedia.org/wiki/Moi_moi', 'live'),
