  ('64e8538c-1e6b-59d0-befc-c3c9da58eda0', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Pepper soup is famous for being…', '["Cold and creamy","Spicy and light","Oily and mild","Thick and sweet"]'::jsonb, 1, 1, 'Catfish pepper soup is also known as ''point and kill''.', 'https://en.wikipedia.org/wiki/Pepper_soup', 'live'),
