  ('f68aaf20-3def-5cb8-92ca-db41636b0012', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kano was famous in the 1960s for pyramids made of what?', '["Groundnut sacks","Cocoa bags","Cotton bales","Rice sacks"]'::jsonb, 0, 3, 'The groundnut pyramids were a symbol of northern agriculture.', 'https://en.wikipedia.org/wiki/Groundnut_pyramids', 'live'),
  ('4469b3c7-3eca-58b1-bc5b-9efc3006986e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Stockfish, used in many Nigerian soups, is mostly imported from which country?', '["Japan","Norway","Morocco","Portugal"]'::jsonb, 1, 3, 'Stockfish is cod that is air-dried in the cold.', 'https://en.wikipedia.org/wiki/Stockfish', 'live'),
  ('e404d4d7-18df-588d-a243-16196b9b79f9', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofada rice is named after a town in which state?', '["Oyo","Ondo","Lagos","Ogun"]'::jsonb, 3, 3, 'It''s a local, unpolished rice with a strong aroma.', 'https://en.wikipedia.org/wiki/Ofada_rice', 'live'),
  ('b829ea88-cb82-555f-a6b9-69278213f720', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which spice blend coats suya?', '["Suya masala","Ras el hanout","Yaji","Berbere"]'::jsonb, 2, 3, 'Yaji typically includes ground kuli-kuli, ginger and chilli.', 'https://en.wikipedia.org/wiki/Suya', 'live'),
  ('7b96d43f-a690-5c8d-9b1b-c626610bd08e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Burukutu is a traditional beer brewed from…', '["Sorghum or millet","Plantain","Barley","Palm sap"]'::jsonb, 0, 3, 'It''s popular in the Middle Belt and north.', 'https://en.wikipedia.org/wiki/Burukutu', 'live'),
  ('c48be014-a5bf-55f7-b9ac-2c151057a13b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Utazi leaves are known for being…', '["Salty","Sweet","Bitter","Sour"]'::jsonb, 2, 4, 'Utazi is used sparingly in nkwobi and ugba.', 'https://en.wikipedia.org/wiki/Gongronema_latifolium', 'live'),
  ('d8825fd5-dc1a-55f7-bb62-2a000e406391', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofe Owerri is a rich soup from which state?', '["Abia","Enugu","Imo","Anambra"]'::jsonb, 2, 4, 'It''s thickened with cocoyam and packed with meats.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('2fcb92de-2bba-584e-9e53-ba988e0ee163', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ekpang Nkukwo is a Calabar dish made with grated cocoyam wrapped in…', '["Cocoyam or ugu leaves","Corn husks","Moin-moin leaves","Banana leaves"]'::jsonb, 0, 4, 'It''s cooked in a rich palm oil broth with seafood.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('a2bc7569-793a-5219-8ae0-c037f0d37086', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Afia efere is an Efik…', '["White soup","Leaf salad","Pepper sauce","Fish roll"]'::jsonb, 0, 4, 'It is cooked without palm oil.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('dbf8355d-f598-5df4-850c-6f899ae6390a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ukodo is a yam pepper soup associated with which people?', '["Hausa","Urhobo","Kanuri","Tiv"]'::jsonb, 1, 4, 'It''s often cooked with goat meat and lemongrass.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('6747cc19-9ace-5b6f-8353-b782fc03decf', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Miyan taushe is a northern soup made mainly with…', '["Pumpkin","Baobab leaves","Okra","Spinach"]'::jsonb, 0, 4, 'Groundnut paste often thickens it.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('10d95845-66d9-58b5-bb05-5485ec1f34c7', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Agidi (eko) is a solid pudding made from…', '["Beans","Rice","Corn starch (pap)","Cassava"]'::jsonb, 2, 4, 'It''s wrapped in leaves and eaten with stews or akara.', 'https://en.wikipedia.org/wiki/Agidi_(food)', 'live'),
  ('717171ce-521f-59bb-9ae0-a07f8bd92c13', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Dambu nama is a northern dish of…', '["Fermented milk","Shredded fried meat floss","Rice balls","Spiced beans"]'::jsonb, 1, 4, 'It''s often made for festive occasions.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('24b9210a-00fa-52b1-86a6-d5897e9b9214', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which tool is used to whip ewedu soup?', '["Ikoko","Odo","Ijabe","Omorogun"]'::jsonb, 2, 4, 'An omorogun is a wooden stick for turning amala and eba.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('c032ccac-ca37-57b0-b000-6759c8c97201', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'An ''omorogun'' is used in the kitchen to…', '["Grind pepper","Pound yam","Turn swallows like amala and eba","Whip ewedu"]'::jsonb, 2, 4, 'It''s a flat wooden stirring stick.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('412d9578-3158-5eec-9cc4-f1fd8a7cf958', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kunu aya is made from…', '["Tiger nuts","Millet","Sorghum","Coconut"]'::jsonb, 0, 4, 'Tiger nuts are called aya in Hausa.', 'https://en.wikipedia.org/wiki/Kunu', 'live'),
  ('b062bc35-bd75-5465-9c2f-9829d3d1c950', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Nono is the Hausa/Fulani name for…', '["Honey","Fermented milk","Millet","Butter"]'::jsonb, 1, 4, 'Nono is famously paired with fura.', 'https://en.wikipedia.org/wiki/Fura', 'live'),
  ('e1a496e8-be78-5653-b911-261cffa3f11b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Tatashe is…', '["Red bell pepper","Scotch bonnet","Garden egg","Long chilli"]'::jsonb, 0, 4, 'Tatashe gives stews their deep red colour without too much heat.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('5ad81b35-72b7-57fc-9c23-ef2f9681c076', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Shombo is a…', '["Type of fish","Long red chilli pepper","Bean variety","Leafy vegetable"]'::jsonb, 1, 4, 'Shombo, tatashe and rodo form the base of Nigerian stew.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('764f309e-cc11-5912-9d69-bc865a08b25d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Garden egg is a type of…', '["Tomato","Potato","Eggplant","Egg"]'::jsonb, 2, 4, 'Garden eggs are often eaten raw with peanut butter.', 'https://en.wikipedia.org/wiki/Solanum_aethiopicum', 'live'),
  ('7ed32a70-d3e1-5dde-9d96-b89d1bf83908', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ijebu garri is known for being…', '["Smoked and brown","Coarse and red","Yellow and sweet","White, fine and sour"]'::jsonb, 3, 4, 'Yellow garri gets its colour from palm oil.', 'https://en.wikipedia.org/wiki/Garri', 'live'),
  ('6f341f36-07b9-545b-b850-78a9a3f2274f', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The Igbo New Yam festival is called…', '["Ofala","Iri Ji","Eyo","Igue"]'::jsonb, 1, 4, 'It marks the end of the farming season.', 'https://en.wikipedia.org/wiki/New_Yam_Festival_of_the_Igbo', 'live'),
  ('a3762a38-169e-575e-836b-4be578dcbd6c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which Edo dish is called ''black soup'' (omoebe)?', '["Smoked fish stew","A dark herbal leaf soup","Burnt-pot jollof","Charcoal-roasted yam"]'::jsonb, 1, 4, 'It gets its dark colour from blended bitter leaf, scent leaf and uziza.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'in_review'),
  ('7ba7c5ad-37a4-58ce-b7b0-caca1437ed2a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Afang leaves come from which climbing plant?', '["Talinum triangulare","Vernonia amygdalina","Gnetum africanum","Telfairia occidentalis"]'::jsonb, 2, 5, 'Afang is widely harvested from forests in the south.', 'https://en.wikipedia.org/wiki/Gnetum_africanum', 'live'),
  ('d030aab0-9b84-5766-b1fd-ec1b268dfd72', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Waterleaf''s scientific name is…', '["Corchorus olitorius","Piper guineense","Gnetum africanum","Talinum triangulare"]'::jsonb, 3, 5, 'It softens dishes like edikang ikong.', 'https://en.wikipedia.org/wiki/Talinum_fruticosum', 'live'),
  ('26f56b9e-af63-5204-a849-a6454fd033b5', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ogbono seeds come from which tree?', '["Irvingia gabonensis","Elaeis guineensis","Adansonia digitata","Parkia biglobosa"]'::jsonb, 0, 5, 'The tree is also called African bush mango.', 'https://en.wikipedia.org/wiki/Irvingia_gabonensis', 'live'),
  ('9b7001ee-7b6b-518d-994c-7e8c28a65aa9', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Iru/dawadawa is traditionally made from the seeds of which tree?', '["Irvingia gabonensis","Treculia africana","Parkia biglobosa","Vitellaria paradoxa"]'::jsonb, 2, 5, 'Parkia biglobosa is called the African locust bean tree.', 'https://en.wikipedia.org/wiki/Parkia_biglobosa', 'live'),
  ('d23848f5-f4ca-545b-90d2-0c05d3ced27a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The oil palm, source of palm oil, has which scientific name?', '["Cocos nucifera","Borassus aethiopum","Raphia hookeri","Elaeis guineensis"]'::jsonb, 3, 5, 'The oil palm is native to West and Central Africa.', 'https://en.wikipedia.org/wiki/Elaeis_guineensis', 'live'),
  ('f2a0e5c3-bf0b-5998-8c57-7cde25041567', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Bitter leaf''s scientific name is…', '["Gongronema latifolium","Vernonia amygdalina","Ocimum gratissimum","Piper guineense"]'::jsonb, 1, 5, 'It is used in ofe onugbu and as a herbal remedy.', 'https://en.wikipedia.org/wiki/Vernonia_amygdalina', 'live'),
  ('3a997530-5a85-56a7-9cf9-1b777d61f756', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ewedu is made from the leaves of which plant?', '["Amaranthus hybridus","Corchorus olitorius","Telfairia occidentalis","Talinum triangulare"]'::jsonb, 1, 5, 'The same plant is used to make jute fibre.', 'https://en.wikipedia.org/wiki/Corchorus_olitorius', 'live'),
  ('f6324462-4b1c-52e1-9600-3491762a9318', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which spice, called ''uda'' in Igbo, comes from the seed pods of Xylopia aethiopica?', '["Grains of Selim","Calabash nutmeg","Grains of paradise","Alligator pepper"]'::jsonb, 0, 5, 'It is used in pepper soup and post-natal dishes.', 'https://en.wikipedia.org/wiki/Xylopia_aethiopica', 'live'),
  ('b60b8f9e-24f2-5a49-95b9-bd544666230e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Alligator pepper is also known as…', '["Grains of paradise","Calabash nutmeg","West African pepper","Grains of Selim"]'::jsonb, 0, 5, 'It is widely used in traditional ceremonies.', 'https://en.wikipedia.org/wiki/Aframomum_melegueta', 'live'),
  ('2780f986-81ff-5922-845b-61efdb1ed515', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Shea butter comes from which tree?', '["Parkia biglobosa","Vitellaria paradoxa","Irvingia gabonensis","Elaeis guineensis"]'::jsonb, 1, 5, 'Nigeria is one of the largest producers of shea nuts.', 'https://en.wikipedia.org/wiki/Vitellaria', 'live'),
  ('b19a4802-6ca2-5505-9050-e5184e9dc9bf', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The kola nut, important in Igbo hospitality, comes from which genus?', '["Coffea","Garcinia","Cola","Theobroma"]'::jsonb, 2, 5, 'Bitter kola is a different plant, Garcinia kola.', 'https://en.wikipedia.org/wiki/Kola_nut', 'live'),
  ('3350b5d1-38a0-588a-9e9d-eb9e469f113a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Bitter kola belongs to which genus?', '["Piper","Garcinia","Xylopia","Cola"]'::jsonb, 1, 5, 'It is chewed for its bitter taste and believed health benefits.', 'https://en.wikipedia.org/wiki/Garcinia_kola', 'live')
